# C:\swarm-cortex-setup.ps1  -- run: powershell -ExecutionPolicy Bypass -File .\swarm-cortex-setup.ps1
$dest = "C:\"
$zip = Join-Path $env:TEMP "swarm-cortex.zip"
[IO.File]::WriteAllBytes($zip, [Convert]::FromBase64String(""))
if (Test-Path "C:\swarm") { Write-Host "C:\swarm exists - not overwriting. Rename it and rerun."; exit 1 }
Expand-Archive -Path $zip -DestinationPath $dest
Write-Host "Unpacked to C:\swarm. Launching setup menu..."
Start-Process "C:\swarm\setup.bat" -WorkingDirectory "C:\swarm"
